CREATE OR REPLACE FUNCTION FN_GET_TICKET_PRICE 
(
  p_ticket_type_id IN NUMBER
) RETURN NUMBER AS 
  v_price NUMBER;
BEGIN
  SELECT UNIT_PRICE INTO v_price
  FROM PRICE_LIST_ITEMS
  WHERE TICKET_TYPES_TICKET_TYPE_ID = p_ticket_type_id
    AND SYSDATE BETWEEN VALID_FROM AND NVL(VALID_TO, SYSDATE + 1)
    AND ROWNUM = 1;
  RETURN v_price;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    RETURN 0;
END FN_GET_TICKET_PRICE;
/

