CREATE OR REPLACE FUNCTION FN_IS_ATTRACTION_AVAILABLE 
(
  p_attraction_id IN NUMBER
) RETURN NUMBER AS 
  v_status VARCHAR2(20);
BEGIN
  SELECT STATUS INTO v_status
  FROM ATTRACTIONS
  WHERE ATTRACTION_ID = p_attraction_id;
  IF v_status = 'OPEN' THEN
    RETURN 1;
  ELSE
    RETURN 0;
  END IF;
EXCEPTION
