CREATE OR REPLACE PROCEDURE SP_CHECK_LOW_STOCK 
AS 
BEGIN
  FOR r_item IN (SELECT NAME, QUANTITY, MIN_STOCK FROM INVENTORY WHERE QUANTITY <= MIN_STOCK) LOOP
    DBMS_OUTPUT.PUT_LINE('VAROVÁNÍ: Položka ' || r_item.NAME || 
                         ' má nízký stav zásob: ' || r_item.QUANTITY || 
                         ' (Minimum: ' || r_item.MIN_STOCK || ')');
  END LOOP;
END SP_CHECK_LOW_STOCK;
/

CREATE OR REPLACE PROCEDURE SP_CREATE_BOOKING 
(
  p_visitor_id IN NUMBER,
  p_notes IN VARCHAR2,
  p_booking_id OUT NUMBER 
) AS 
BEGIN
  INSERT INTO BOOKINGS (VISITORS_VISITOR_ID, STATUS, NOTES, CREATED_AT, TOTAL_AMOUNT)
  VALUES (p_visitor_id, 'PENDING', p_notes, SYSTIMESTAMP, 0)
  RETURNING BOOKING_ID INTO p_booking_id;
  UPDATE BOOKINGS 
  SET BOOKING_REF = 'BK-' || TO_CHAR(SYSDATE, 'YYYY') || '-' || p_booking_id
  WHERE BOOKING_ID = p_booking_id;
  COMMIT;
END SP_CREATE_BOOKING;
/

