CREATE OR REPLACE PROCEDURE SP_DAILY_REVENUE_REPORT 
(
  p_report_date IN DATE,
  o_total_revenue OUT NUMBER
) AS 
  v_bookings_total NUMBER;
  v_concessions_total NUMBER;
BEGIN
  -- Tržby z rezervací
  SELECT NVL(SUM(TOTAL_AMOUNT), 0) INTO v_bookings_total
  FROM BOOKINGS
  WHERE TRUNC(CREATED_DATE) = TRUNC(p_report_date)
    AND STATUS = 'CONFIRMED';

  -- Tržby z prodeje na stáncích
  SELECT NVL(SUM(AMOUNT), 0) INTO v_concessions_total
  FROM CONCESSION_SALES
  WHERE TRUNC(SALE_DATE) = TRUNC(p_report_date);

  o_total_revenue := v_bookings_total + v_concessions_total;
  
  DBMS_OUTPUT.PUT_LINE('Report pro datum: ' || TO_CHAR(p_report_date, 'DD.MM.YYYY'));
  DBMS_OUTPUT.PUT_LINE('Celkem tržba: ' || o_total_revenue);
END SP_DAILY_REVENUE_REPORT;
/

CREATE OR REPLACE PROCEDURE SP_GET_VISITOR_STATS 
(
  p_visitor_id IN NUMBER,
  o_total_spent OUT NUMBER,
  o_visit_count OUT NUMBER,
  o_last_visit OUT DATE
) AS 
BEGIN
  -- Agregace
  SELECT NVL(SUM(TOTAL_AMOUNT), 0), COUNT(*), MAX(CREATED_DATE)
  INTO o_total_spent, o_visit_count, o_last_visit
  FROM BOOKINGS
  WHERE VISITORS_VISITOR_ID = p_visitor_id
    AND STATUS != 'CANCELLED';

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    o_total_spent := 0;
    o_visit_count := 0;
    o_last_visit := NULL;
END SP_GET_VISITOR_STATS;
/

CREATE OR REPLACE PROCEDURE SP_REGISTER_VISITOR 
(
  p_first_name IN VARCHAR2,
  p_last_name IN VARCHAR2,
  p_email IN VARCHAR2,
  p_address_id IN NUMBER,
  p_dob IN DATE
) AS 
BEGIN
  INSERT INTO VISITORS (FIRST_NAME, LAST_NAME, EMAIL, ADDRESS_ADDRESS_ID, DATE_OF_BIRTH, CREATED_AT, UPDATED_AT)
  VALUES (p_first_name, p_last_name, p_email, p_address_id, p_dob, SYSTIMESTAMP, SYSTIMESTAMP);
  COMMIT;
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    RAISE;
END SP_REGISTER_VISITOR;
/

CREATE OR REPLACE PROCEDURE SP_SET_ATTRACTION_STATUS 
(
  p_attraction_id IN NUMBER,
  p_new_status IN VARCHAR2,
  p_staff_id IN NUMBER
) AS 
BEGIN
  IF p_new_status NOT IN ('OPEN', 'CLOSED', 'MAINTENANCE') THEN
     RAISE_APPLICATION_ERROR(-20001, 'Invalid Status');
  END IF;

  UPDATE ATTRACTIONS
  SET STATUS = p_new_status,
      UPDATED_AT = SYSTIMESTAMP,
      UPDATED_BY_USER_ID = p_staff_id
  WHERE ATTRACTION_ID = p_attraction_id;
  COMMIT;
END SP_SET_ATTRACTION_STATUS;
/

