CREATE OR REPLACE PROCEDURE SP_UPDATE_LOYALTY_TIERS 
AS 
    CURSOR c_high_spenders IS
        SELECT b.VISITORS_VISITOR_ID, SUM(b.TOTAL_AMOUNT) as total_spent
        FROM BOOKINGS b
        WHERE b.STATUS = 'COMPLETED'
        GROUP BY b.VISITORS_VISITOR_ID
        HAVING SUM(b.TOTAL_AMOUNT) > 1000;
        
    v_visitor_id NUMBER;
    v_total NUMBER;
BEGIN
    OPEN c_high_spenders;
    LOOP
        FETCH c_high_spenders INTO v_visitor_id, v_total;
        EXIT WHEN c_high_spenders%NOTFOUND;
        -- Logika aktualizace
        UPDATE LOYALTY_POINTS
        SET TIER = 'SILVER',
            UPDATED_AT = SYSTIMESTAMP
        WHERE VISITORS_VISITOR_ID = v_visitor_id
          AND TIER = 'BRONZE';
    END LOOP;
    CLOSE c_high_spenders;
    COMMIT;
END SP_UPDATE_LOYALTY_TIERS;
/

