CREATE OR REPLACE VIEW V_AREA_HIERARCHY ( AREA_ID, NAME, PARENT_AREA_ID, LVL, PATH_TXT ) AS
SELECT AREA_ID, NAME, PARENT_AREA_ID,
       LEVEL AS LVL,
       SYS_CONNECT_BY_PATH(NAME,' / ') AS PATH_TXT
  FROM PARK_AREAS
 START WITH PARENT_AREA_ID IS NULL
CONNECT BY PRIOR AREA_ID = PARENT_AREA_ID 
;

CREATE OR REPLACE VIEW V_BOOKING_OVERVIEW ( BOOKING_ID, BOOKING_REF, VISITOR_NAME, BOOKING_STATUS, TOTAL_AMOUNT, TOTAL_PAID ) AS
SELECT
  b.BOOKING_ID,
  b.BOOKING_REF,
  (SELECT FIRST_NAME||' '||LAST_NAME FROM VISITORS v WHERE v.VISITOR_ID = b.VISITORS_VISITOR_ID) AS VISITOR_NAME,
  b.STATUS AS BOOKING_STATUS,
  NVL(b.TOTAL_AMOUNT,0) AS TOTAL_AMOUNT,
  NVL((SELECT SUM(p.AMOUNT) FROM PAYMENTS p WHERE p.BOOKINGS_BOOKING_ID = b.BOOKING_ID AND p.STATUS IN ('COMPLETED','REFUNDED')),0) AS TOTAL_PAID
FROM BOOKINGS b 
;

CREATE OR REPLACE VIEW V_DB_OBJECTS ( object_type, object_name, status, last_ddl_time ) AS
SELECT o.object_type, o.object_name, o.status, o.last_ddl_time
  FROM USER_OBJECTS o
 WHERE o.object_type IN ('TABLE','VIEW','SEQUENCE','TRIGGER','INDEX')
 ORDER BY o.object_type, o.object_name 
;

CREATE OR REPLACE VIEW V_VISITORS_PUBLIC ( VISITOR_ID, FIRST_NAME, LAST_NAME, AGE_YEARS ) AS
SELECT VISITOR_ID, FIRST_NAME, LAST_NAME,
       CASE WHEN DATE_OF_BIRTH IS NOT NULL THEN TRUNC(MONTHS_BETWEEN(SYSDATE, DATE_OF_BIRTH)/12) END AS AGE_YEARS
  FROM VISITORS 
;

CREATE OR REPLACE TRIGGER TRG_CHECK_MEMBERSHIP_DATES 
    BEFORE INSERT OR UPDATE ON MEMBERSHIPS 
    FOR EACH ROW 
BEGIN 
    IF :NEW.END_DATE IS NOT NULL AND :NEW.END_DATE < :NEW.START_DATE THEN
        RAISE_APPLICATION_ERROR(-20002, 'End Date cannot be earlier than Start Date!');
    END IF;
END; 
/

CREATE OR REPLACE TRIGGER TRG_LOG_ATTRACTION_CHANGE 
    AFTER UPDATE OF STATUS ON ATTRACTIONS 
    FOR EACH ROW 
BEGIN 
    IF :OLD.STATUS != :NEW.STATUS THEN
        INSERT INTO OPERATIONAL_LOGS (
            LOG_TYPE, 
            DESCRIPTION, 
            RELATED_TABLE, 
            RELATED_ID, 
            CREATED_AT
        ) VALUES (
            'STATUS_CHANGE', 
            'Attraction ' || :NEW.NAME || ' changed status from ' || :OLD.STATUS || ' to ' || :NEW.STATUS, 
            'ATTRACTIONS', 
            :NEW.ATTRACTION_ID, 
            SYSTIMESTAMP
        );
    END IF;
END; 
/

CREATE OR REPLACE TRIGGER TRG_RECALC_BOOKING_TOTAL 
    AFTER INSERT OR DELETE OR UPDATE ON BOOKING_ITEMS 
    FOR EACH ROW 
DECLARE
  v_booking_id NUMBER;
BEGIN
  IF :NEW.BOOKINGS_BOOKING_ID IS NOT NULL THEN
     v_booking_id := :NEW.BOOKINGS_BOOKING_ID;
  ELSE
     v_booking_id := :OLD.BOOKINGS_BOOKING_ID;
  END IF;
  UPDATE BOOKINGS
  SET TOTAL_AMOUNT = (
      SELECT NVL(SUM(QUANTITY * UNIT_PRICE), 0)
      FROM BOOKING_ITEMS
      WHERE BOOKINGS_BOOKING_ID = v_booking_id
  ),
  UPDATED_AT = SYSTIMESTAMP
  WHERE BOOKING_ID = v_booking_id;
END; 
/

